from pathlib import Path
import json,sys,copy
P=Path(__file__).resolve().parent;B=P.parents[3];sys.path.insert(0,str(B))
from run_exhaustive import validate_answer
from substantive_impact import plain
sources=json.loads((P/'source.json').read_text())
context=json.loads((P/'context.json').read_text())
by={s['number']:s for s in sources}
law=next(s for s in context if s['number']=='L1221-12')
if 'L1221-12' not in by:
 sources.append(copy.deepcopy(law));by['L1221-12']=sources[-1]
transition="Ces dispositions s'appliquent à compter de l'entrée en vigueur de la réforme. Les déclarations régulièrement effectuées restent valables et n'ont pas à être recommencées. Les obligations de déclaration avant l'embauche, d'affiliation, de suivi de santé et de paiement des cotisations demeurent applicables selon leurs règles propres."
bodies={}
bodies['R1221-3']=by['R1221-3']['source_xml'].replace(" et au service de santé au travail mentionné au 1° de l'article R. 1221-1",'')+"\n<p>Le dépôt auprès de cet organisme satisfait à la déclaration préalable dans les conditions de l'article L. 1221-10. L'organisme transmet aux destinataires, notamment au service de santé au travail concerné, les informations nécessaires selon l'article R. 1221-14 ; aucun second dépôt de cette déclaration auprès de ce service n'est demandé à l'employeur. Les conditions de son adhésion et du suivi de la santé du salarié restent applicables.</p><p>"+transition+'</p>'
bodies['R1221-5']="""<p>La déclaration préalable à l'embauche est effectuée par voie électronique, sous réserve des voies de déclaration ouvertes ci-après. L'obligation de déclaration électronique prévue à l'article D. 1221-18 reste applicable aux employeurs qui y sont soumis.</p>
<p>Lorsqu'une autre voie est légalement ouverte, la déclaration est effectuée au moyen du formulaire fixé par arrêté des ministres chargés du travail et de la sécurité sociale ainsi que, pour un salarié relevant du régime de protection sociale agricole, du ministre chargé de l'agriculture.</p>
<p>L'employeur adresse ce formulaire, signé par lui, à l'organisme mentionné à l'article R. 1221-3 par lettre recommandée avec demande d'avis de réception envoyée au plus tard le dernier jour ouvrable précédant l'embauche, le cachet de la poste faisant foi. Il peut également le remettre à cet organisme contre récépissé avant la prise effective du travail, lorsque l'organisme offre ce mode de réception. Aucun recours exclusif à l'envoi recommandé ni paiement de ses frais ne peut être exigé lorsque cette remise régulière est effectuée. L'employeur n'est pas tenu de conserver un double de la lettre, du formulaire ou du récépissé postal sur le seul fondement du présent article ; il peut conserver les justificatifs utiles à la preuve de sa déclaration.</p>
<p>L'indisponibilité de l'un des moyens de transmission mentionnés ci-dessus n'exonère pas l'employeur de son obligation de déclaration par l'autre moyen. Les garanties, sanctions et dispenses ayant un fondement distinct ne sont pas modifiées par le présent article.</p>
<p>"""+transition+'</p>'
bodies['R1221-6']="""<p>Lorsque la déclaration est effectuée par voie électronique par un employeur relevant du régime général de sécurité sociale préalablement inscrit à un service d'authentification, la formalité est réputée accomplie au moyen du numéro d'identification de l'établissement employeur, du numéro national d'identification du salarié déjà immatriculé lorsque les autres données exactes et à jour requises sont déjà légalement accessibles à l'organisme destinataire, ainsi que de la date et de l'heure d'embauche mentionnées au 3° de l'article R. 1221-1. L'ancienneté d'une déclaration précédente ne fait pas obstacle, à elle seule, à cette réutilisation.</p>
<p>Les informations que l'organisme ne détient pas et ne peut légalement obtenir restent fournies dans les seules limites de l'article R. 1221-1. La nature ou la durée du contrat et la durée de l'essai supprimées de cette déclaration ne sont pas réintroduites par le présent article. Aucun justificatif confirmant l'absence de changement d'une donnée déjà réutilisable n'est exigé ; les données inexactes peuvent être corrigées.</p>
<p>"""+transition+'</p>'
bodies['R1221-8']="""<p>Le présent article est abrogé à compter de l'entrée en vigueur de la réforme.</p>
<p>L'obligation propre à cet article de conserver l'avis de réception de la déclaration préalable à l'embauche n'est plus exigible, y compris pour les avis déjà reçus. Les avis et autres justificatifs existants restent utilisables pour prouver les déclarations effectuées ; leur destruction n'est pas imposée. L'employeur peut conserver les pièces utiles dans le respect des règles qui leur sont applicables.</p>
<p>Les modalités du contrôle restent celles de l'article R. 1221-12. Les obligations de déclaration des rémunérations et les autres obligations de conservation reposant sur un fondement distinct sont maintenues. La conservation des données par l'organisme destinataire reste régie par l'article R. 1221-16 ; aucune prolongation de cette durée n'est créée.</p>"""
bodies['R1221-12']="""<p>Sur toute demande des agents de contrôle mentionnés à l'article L. 8271-7, l'employeur communique les éléments qu'il détient permettant de vérifier qu'il a effectué la déclaration préalable à l'embauche du salarié. Il peut présenter l'avis de réception, les références du dépôt ou les autres justificatifs disponibles. Il n'est pas tenu de reconstituer un avis ou une copie dont la conservation n'est plus exigée par les articles R. 1221-5 et R. 1221-8.</p>
<p>Lorsque les agents disposent déjà légalement et effectivement des mêmes informations à jour auprès de l'organisme destinataire, cette vérification ne donne pas lieu à une production identique de l'employeur. Le présent article ne leur ouvre aucun accès nouveau aux données et ne réduit pas les pouvoirs de contrôle ayant un fondement distinct. L'absence d'un double dont la conservation n'est pas obligatoire ne constitue pas, à elle seule, la preuve d'une absence de déclaration.</p>
<p>Ces dispositions s'appliquent aux contrôles effectués après leur entrée en vigueur, sans remettre en cause les déclarations régulièrement accomplies ni les autres obligations de preuve et de conservation légalement applicables.</p>"""
bodies['R1221-13']="""<p>Les seules pénalités prévues par la rédaction antérieure de l'article L. 1221-11 qui sont devenues définitives avant l'entrée en vigueur de son abrogation restent recouvrables dans les limites prévues par cet article. Leur recouvrement demeure soumis aux modalités et conditions antérieurement applicables :</p>
<p>1° Dans les secteurs autres que le secteur agricole, selon l'article R. 243-19 du code de la sécurité sociale ;</p>
<p>2° Dans le secteur agricole, selon l'article L. 725-3 du code rural et de la pêche maritime.</p>
<p>Le présent article n'autorise aucune pénalité nouvelle sur le fondement de l'article L. 1221-11 abrogé. Les manquements pour lesquels la pénalité n'était pas définitive bénéficient des dispositions de suppression de cet article. Les autres sanctions, notamment celles ayant un fondement distinct et la pénalité de déclaration dématérialisée de l'article D. 1221-19, ne sont pas supprimées par ce seul renvoi. Les recours et restitutions légalement ouverts restent applicables.</p>"""
old=by['R1221-18']['source_xml']
oldfirst="correspond aux données d'état civil qui figurent sur cette même déclaration."
assert oldfirst in old
bodies['R1221-18']=old.replace(oldfirst,"correspond aux données d'état civil régulièrement requises par l'article R. 1221-1 qui figurent dans cette déclaration ou sont déjà légalement accessibles à la caisse pour cette vérification. L'absence de mentions d'état civil que cet article ne demande pas en présence d'un numéro national d'identification n'impose ni nouvelle déclaration ni justificatif de l'employeur sur ce seul fondement.")+'\n<p>Cette coordination s’applique aux déclarations effectuées après l’entrée en vigueur de la réforme, sans rétablir les données supprimées par l’article R. 1221-1. Les règles distinctes de vérification de l’identité, de correction contradictoire de la déclaration sociale nominative et de protection des données restent applicables.</p>'
prior=law['previous_draft']['proposed_xml'];needle='<p>2° Les modalités de recouvrement de la pénalité prévue à l’article L. 1221-11.</p>'
assert needle in prior
bodies['L1221-12']=prior.replace(needle,"<p>2° Les modalités de recouvrement des seules pénalités prévues par la rédaction antérieure de l'article L. 1221-11 et devenues définitives avant l'entrée en vigueur de son abrogation, dans les limites de la transition prévue par cet article.</p>")+"<p>Aucune disposition réglementaire prise sur le fondement du présent article ne peut rétablir pour l'avenir la pénalité supprimée de l'article L. 1221-11 ni imposer les dépôts identiques auprès d'autres organismes supprimés par l'article L. 1221-10. Les autres obligations et sanctions ayant un fondement distinct restent applicables.</p>"
notes={
'R1221-3':"Le dépôt unique est déjà porté par L1221-10 proposé : l'article retire son second destinataire direct sans revendiquer une seconde fusion. Les six opérations de R1221-2 et les transmissions de R1221-14 restent entières, aucune affiliation ni visite supprimée.",
'R1221-5':"Seuls le recommandé exclusif lorsque la remise contre récépissé est offerte et la conservation obligatoire de ses doubles sont allégés. Ni nouveau guichet ni accès technique universel promis. Les plus de50DPAE de D1221-18 gardent leur voie obligatoire ; le délai postal antérieur et la déclaration avant travail restent. Le CRPA ne transforme pas la suppression d'une conservation privée en simple réemploi d'une donnée par l'administration. Portée à contre-lire, aucune économie nationale chiffrée.",
'R1221-6':"Coordonne la disparition du4° de R1221-1 et la réutilisation déjà prévue dans cet article et par CRPA L113-12. Ne compte aucune nouvelle suppression nette de donnée. Authentification antérieure, immatriculation et vérification de données à jour restent nécessaires ; aucune donnée étrangère non légalement accessible n'est réputée détenue.",
'R1221-8':"Suppression du seul archivage de l'avis, coordonnée avec R1221-5 et R1221-12. La source renvoie pour les non-agricoles à R243-14 qui traite désormais du non-cumul de sanctions et non d'une déclaration : pas de réduction d'un délai source actuel affirmée. Les formalités agricoles distinctes ne sont ni abrogées ni certifiées par cette passe ; le renvoi supprimé n'est pas remplacé par une nouvelle demande. Même mesure de conservation, pas un second gain.",
'R1221-12':"Le pouvoir de contrôle est conservé. La production d'un double non obligatoire ne revient pas par le contrôle. Les informations déjà légalement et effectivement accessibles ne donnent aucun droit d'accès supplémentaire. La seule reprise du principe CRPA n'est pas présentée comme nouveau gain ; tous les effets sont des coordinations de la suppression d'archivage.",
'R1221-13':"L1221-11 proposé supprime la pénalité future mais conserve les seules pénalités antérieures définitives. Le renvoi réglementaire et L1221-12 sont limités exactement à ce stock. R243-19 source lu entier ; aucune création de dette, amnistie plus large ni suppression de la pénalité distincte D1221-19. Le texte rural inchangé ne fait pas l'objet d'une validation globale.",
'R1221-18':"L'organisme continue son rapprochement d'identité et le bilan d'identification existant. Le premier alinéa tient compte de la dispense d'état civil quand R1221-1 comporte déjà le NIR ; aucun retour de données supprimées via un justificatif. La correction DSN de l'alinéa2 est inchangée et reste soumise à L133-5-3-1. Aucun automatisme de rectification nouveau ni nouvelle garantie d'identité sans preuve.",
'L1221-12':"Conserve le1° entier du projet précédent et limite son2° à la transition expressément prévue par L1221-11. Aucune sanction future n'est déléguée ; la pénalité D1221-19 distincte n'est pas supprimée. Seule coordination de la suppression déjà proposée, aucune nouvelle baisse de prélèvement comptée."
}
reasons={n:notes[n].split('. ')[0]+'.' for n in notes}
retained={
'R1221-2':"La DPAE satisfait déjà six opérations en une déclaration. Maintenir ce circuit, les affiliations et visites de santé, sans revendiquer une nouvelle fusion déjà faite.",
'R1221-4':"La fenêtre de huit jours reste la règle de transmission avant l'embauche ; aucun délai de prise d'emploi ni coût de recrutement n'est supposé supprimé par une reformulation.",
'R1221-7':"Conserver la délivrance de l'accusé sous cinq jours et son régime probatoire. Les deux jours concernent la contestation de ses données et la preuve, pas une attente préalable à l'embauche ; aucune forclusion générale de rectification ni délai de recrutement n'est inventé.",
'R1221-9':"Le contrat écrit comportant l'organisme destinataire dispense déjà de remettre la copie de DPAE. Préserver cette voie favorable et la copie alternative, sans prétendre créer une dispense existante.",
'R1221-14':"La transmission interorganismes est déjà obligatoire. Conserver compétences et appréciation de validité ; c'est le circuit utilisé par le dépôt unique, pas une fusion nouvellement créée.",
'R1221-15':"Les conventions règlent les échanges et leur rémunération entre organismes, sans créer de formalité distincte de l'employeur. Aucun coût public supprimé n'est déduit d'une simple suppression de convention.",
'R1221-16':"Conserver les six mois de données détenues par le destinataire, sans allonger la rétention à raison du nouvel archivage facultatif de l'employeur ni inventer un accès au-delà de cette durée.",
'D1221-18':"Le seuil de plus de50déclarations impose une transmission électronique pour les employeurs du régime général hors particuliers et pour les agricoles. Pas d'exception implicite via le nouveau mode papier des employeurs non soumis.",
'D1221-19':"La pénalité propre au défaut de dématérialisation reste distincte de celle supprimée à L1221-11. Aucun renvoi ne doit la supprimer ou la compter comme déjà supprimée par erreur."
}
answers=[]
for s in sources:
 n=s['number'];body=bodies.get(n);row={k:s[k] for k in ['code_id','source_id','source_sha256','number']};effects=[]
 cl='retained_necessary' if body is None else 'coordination_only'
 if body:
  measure='dpae-preuves-sans-archivage-impose';kind='coordination'
  if n=='R1221-5':cl='material_reduction';kind='obligation_removed'
  elif n=='R1221-3':measure='dpae-depot-unique-organismes'
  elif n in ['R1221-6','R1221-18']:measure='dpae-identification-sans-donnees-redondantes'
  elif n in ['R1221-13','L1221-12']:measure='dpae-penalite-supprimee-transition'
  quotes={
   'R1221-3':("et au service de santé au travail mentionné au 1° de l'article R. 1221-1","aucun second dépôt de cette déclaration auprès de ce service n'est demandé à l'employeur"),
   'R1221-5':("L'employeur conserve un double de la lettre et le récépissé postal","L'employeur n'est pas tenu de conserver un double de la lettre, du formulaire ou du récépissé postal"),
   'R1221-6':("des mentions prévues aux 3° et 4° de l'article R. 1221-1","la date et de l'heure d'embauche mentionnées au 3° de l'article R. 1221-1"),
   'R1221-8':("L'employeur conserve l'avis de réception","L'obligation propre à cet article de conserver l'avis de réception de la déclaration préalable à l'embauche n'est plus exigible"),
   'R1221-12':("s'il est encore tenu de le conserver en application de l'article R. 1221-8","Il n'est pas tenu de reconstituer un avis ou une copie dont la conservation n'est plus exigée"),
   'R1221-13':("La pénalité prévue à l'article L. 1221-11","Les seules pénalités prévues par la rédaction antérieure de l'article L. 1221-11 qui sont devenues définitives"),
   'R1221-18':("correspond aux données d'état civil qui figurent sur cette même déclaration","correspond aux données d'état civil régulièrement requises par l'article R. 1221-1"),
   'L1221-12':("Les modalités de recouvrement de la pénalité prévue à l'article L. 1221-11","des seules pénalités prévues par la rédaction antérieure de l'article L. 1221-11 et devenues définitives")}
  before,after=quotes[n]
  effects=[dict(kind=kind,measure_id=measure,description=reasons[n],before='Règle source entière et ses obligations ou renvois particuliers.',after=reasons[n],source_quote=before,proposed_quote=after,unit='legal_duty' if kind=='obligation_removed' else 'other',affected_population='Employeurs et organismes destinataires dans le champ exact du présent article.',conditions_and_transition='Effets après entrée en vigueur ; déclarations déjà effectuées et obligations distinctes préservées. Les seules anciennes pénalités définitives restent recouvrables.',replacement_or_new_burdens='Aucune déclaration, preuve ou inscription nouvelle ; aucun système nouveau présumé disponible. Les données obligatoires et contrôles distincts restent applicables. Aucun coût national ni gain net global établi.')]
  if n=='R1221-5':effects[0]['before']='Archivage obligatoire du double de lettre et du récépissé postal ; recommandé exclusif pour le formulaire postal.';effects[0]['after']='Archivage de ces doubles facultatif ; remise contre récépissé également permise quand elle est offerte aux employeurs autorisés à déclarer hors voie électronique.'
 reason=reasons.get(n,retained.get(n));note=notes.get(n,retained.get(n))
 row.update(status='rewrite_draft' if body else 'retained_unchanged',proposed_xml=body,reason=reason,review_notes=note,benefit_review='Les voies simplifiées, affiliations et suivi de santé sont préservés, ainsi que les droits acquis, recours et moyens de preuve antérieurs. Les régimes et avantages agricoles ou maritimes distincts ne sont pas retirés par une suppression de copie ou de destinataire. Aucun nouveau droit à des prestations financées n’est inventé.',substantive_impact=dict(version=1,classification=cl,assessment=note,scope_limitations='Passe bornée aux formalités DPAE et renvois expressément corrigés. Le CRPA est pris en compte : son simple rappel ne compte pas comme suppression nette. Aucun gain national de coût ou de délai d’embauche affirmé.',new_burdens_review='Les déclarations avant travail et données nécessaires restent exigées. Aucun nouveau portail ni document de confirmation. Les contrôles et obligations d’affiliation, de santé et de cotisations conservent leurs règles distinctes.',effects=effects))
 if n=='R1221-8':row.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope="Obligation autonome de conserver l'avis de réception DPAE, y compris au-delà du renvoi non agricole devenu sans objet ; autres obligations de conservation et contrôles maintenus.")
 answers.append(row)
validate_answer(answers,sources)
(P/'source.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n')
(P/'answer.json').write_text(json.dumps(answers,ensure_ascii=False,indent=2)+'\n')
print('Prepared',len(answers),'whole entries; one bounded reduction, seven coordinations, nine unchanged')
